mapper.select:
/* SQL_ID: ModelMapper.selectModelTreeList */ WITH RECURSIVE classes (type_model_id, up_model_id, model_id, model_nm, model_logic_nm , abstrt_model_yn, structd_model_yn, structd_model_schma_mtcd, model_data_sttus_mtcd, model_type_mtcd, model_sort_odrg , depth, id_path, nm_path, logic_nm_path, odrg_path, cycle) AS ( SELECT m.type_model_id , m.up_model_id , m.model_id , m.model_nm , m.model_logic_nm , m.abstrt_model_yn , m.structd_model_yn , m.structd_model_schma_mtcd , m.model_data_sttus_mtcd , m.model_type_mtcd , m.model_sort_odrg , 0 , ARRAY [m.model_id::text] , ARRAY [m.model_nm::text] , ARRAY [m.model_logic_nm::text] , ARRAY [ROW_NUMBER() OVER(ORDER BY m.model_sort_odrg, m.model_nm)::int4] , false FROM dtmeta.tb_meta_model m WHERE m.up_model_id IS NULL UNION ALL SELECT m.type_model_id , m.up_model_id , m.model_id , m.model_nm , m.model_logic_nm , m.abstrt_model_yn , m.structd_model_yn , m.structd_model_schma_mtcd , m.model_data_sttus_mtcd , m.model_type_mtcd , m.model_sort_odrg , c.depth + 1 , ARRAY_APPEND(c.id_path, m.model_id::text) , ARRAY_APPEND(c.nm_path, m.model_nm::text) , ARRAY_APPEND(c.logic_nm_path, m.model_logic_nm::text) , ARRAY_APPEND(c.odrg_path, ROW_NUMBER() OVER(ORDER BY m.model_sort_odrg, m.model_nm)::int4) , m.model_id = ANY(c.id_path) FROM dtmeta.tb_meta_model m , classes c WHERE m.up_model_id = c.model_id
AND m.model_type_mtcd = #{modelTypeMtcd}
AND m.structd_model_yn = #{structdModelYn}
AND m.model_data_sttus_mtcd = #{modelDataSttusMtcd}
AND NOT CYCLE ) SELECT m.depth , m.model_id , m.model_nm , m.model_logic_nm , m.type_model_id , t1.model_nm AS type_model_nm , t1.model_logic_nm AS type_model_logic_nm , m.up_model_id , m.abstrt_model_yn , m.structd_model_yn , m.structd_model_schma_mtcd , m.model_data_sttus_mtcd , m.id_path , m.nm_path , m.logic_nm_path , m.odrg_path FROM classes m LEFT OUTER JOIN dtmeta.tb_meta_model t1 ON m.type_model_id = t1.model_id ORDER BY m.odrg_path

SELECT /* SQL_ID: ModelMapper.selectModelUriCheck */ SUM(cnt) FROM ( SELECT COUNT(model.model_data_uri) AS cnt FROM dtmeta.tb_meta_model model WHERE UPPER(model.model_data_uri) = UPPER(#{modelDataUri}) AND model.up_model_id = 'Class'
AND model.model_id != #{modelId}
UNION ALL /* 예약된 리소스 URI */ SELECT COUNT(code.mtcd) AS cnt FROM dtmeta.tb_portal_code code WHERE code.mtcd_grp_id = 'MCG00022' AND code.mtcd_use_yn = 'Y' AND UPPER(code.mtcd) = UPPER(#{modelDataUri}) ) a

mapper.update:
		UPDATE /* SQL_ID: ModelMapper.updateDataTypeModel*/
               dtmeta.tb_meta_model
		   SET model_logic_nm               = #{modelLogicNm}
			 , model_desc                   = #{modelDesc}
			 , model_data_sttus_mtcd        = #{modelDataSttusMtcd}
			 , model_sort_odrg              = #{modelSortOdrg}
			 , data_type_mtcd               = #{dataTypeMtcd}
			 , data_type_val_exam			= #{dataTypeValExam}
			 , mtcd_grp_id                  = #{mtcdGrpId}
			 , use_lang_mtcd                = #{useLangMtcd}
			 , model_amdr_id                = #{modelAmdrId}
			 , model_amdr_nm                = #{modelAmdrNm}
			 , model_amd_dt                 = current_timestamp
		 WHERE model_id		        		= #{modelId}

		UPDATE /* SQL_ID: ModelMapper.updateModelSttus*/
               dtmeta.tb_meta_model
		   SET model_data_sttus_mtcd        = #{modelDataSttusMtcd}
			 , model_amdr_id                = #{modelAmdrId}
			 , model_amdr_nm                = #{modelAmdrNm}
			 , model_amd_dt                 = current_timestamp
		 WHERE model_id		        		= #{modelId}

mapper.delete:
DELETE /* SQL_ID: ModelMapper.deleteModel*/ 
FROM dtmeta.tb_meta_model
WHERE model_id = #{modelId}

mapper.insert:
	INSERT /* SQL_ID: ModelMapper.insertTypeModel */
      INTO dtmeta.tb_meta_model
		 ( 
		   model_id
		 , up_model_id
		 , type_model_id
		 , model_nm
		 , model_logic_nm
		 , model_desc
		 , model_data_sttus_mtcd
		 , model_sort_odrg
		 , model_type_mtcd
		 , abstrt_model_yn
		 , structd_model_yn
		 , structd_model_schma_mtcd
		 , model_data_uri
		 , model_data_id_pfix
		 , data_type_mtcd
		 , data_type_val_exam
		 , mtcd_grp_id
		 , use_lang_mtcd
		 , model_regr_id
		 , model_regr_nm
		 , model_reg_dt
		 , model_amdr_id
		 , model_amdr_nm
		 , model_amd_dt
		 ) 
    VALUES 
		 ( 
		   #{modelId}
		 , 'Class'
		 , #{typeModelId}
		 , #{modelNm}
		 , #{modelLogicNm}
		 , #{modelDesc}
		 , #{modelDataSttusMtcd}
		 , #{modelSortOdrg}
		 , 'object_type'
		 , 'Y'
		 , #{structdModelYn}
		 , #{structdModelSchmaMtcd}
		 , #{modelDataUri}
		 , #{modelDataIdPfix}
		 , #{dataTypeMtcd}
		 , #{dataTypeValExam}
		 , #{mtcdGrpId}
		 , #{useLangMtcd}
		 , #{modelRegrId}
		 , #{modelRegrNm}
		 , current_timestamp
		 , #{modelAmdrId}
		 , #{modelAmdrNm}
		 , current_timestamp
		 )

